import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // P: length of the longest non-decreasing prefix.
        int p = 1;
        while (p < n && a[p - 1] <= a[p]) p++;
        if (p == n) { System.out.println((long) n * (n + 1) / 2 - 1); return; }
        // S: start of the longest non-decreasing suffix.
        int s = n - 1;
        while (s > 0 && a[s - 1] <= a[s]) s--;
        long ans = n - Math.max(1, s); // l = 0: the kept suffix starts at j in [max(1, S), n-1]
        for (int l = 1; l <= p; l++) {
            int lo = Math.max(l + 1, s), hi = n;
            long target = a[l - 1];
            while (lo < hi) { // first j with a[j] >= target in the sorted suffix
                int mid = (lo + hi) >>> 1;
                if (a[mid] < target) lo = mid + 1; else hi = mid;
            }
            ans += n - lo + 1; // j..n-1 plus deleting the whole tail (j = n)
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	// P: length of the longest non-decreasing prefix.
	p := 1
	for p < n && a[p-1] <= a[p] {
		p++
	}
	if p == n {
		fmt.Println(n*(n+1)/2 - 1)
		return
	}
	// S: start of the longest non-decreasing suffix.
	s := n - 1
	for s > 0 && a[s-1] <= a[s] {
		s--
	}
	ans := n - max(1, s) // l = 0: the kept suffix starts at j in [max(1, S), n-1]
	for l := 1; l <= p; l++ {
		lo := max(l+1, s)
		target := a[l-1]
		j := lo + sort.Search(n-lo, func(k int) bool { return a[lo+k] >= target })
		ans += n - j + 1 // j..n-1 plus deleting the whole tail (j = n)
	}
	fmt.Println(ans)
}
